<?php

declare(strict_types=1);

namespace App\Policies;

use App\Models\Admin;
use App\Models\Role;
use Illuminate\Foundation\Auth\User as AuthUser;

/**
 * Generated by Shield, then extended by hand. RoleService enforces the same
 * rules for callers that do not go through the panel.
 */
final class RolePolicy
{
    public function viewAny(AuthUser $actor): bool
    {
        return $actor->can('view_any:role');
    }

    public function view(AuthUser $actor, Role $role): bool
    {
        if (! $actor->can('view:role')) {
            return false;
        }

        return ! $role->isSuperAdmin() || ($actor instanceof Admin && $actor->isSuperAdmin());
    }

    public function create(AuthUser $actor): bool
    {
        return $actor->can('create:role');
    }

    /**
     * super_admin is fixed: it always holds every permission and the kit
     * looks it up by name, so not even a super admin edits or deletes it.
     */
    public function update(AuthUser $actor, Role $role): bool
    {
        return $actor->can('update:role') && ! $role->isSuperAdmin();
    }

    public function delete(AuthUser $actor, Role $role): bool
    {
        return $actor->can('delete:role') && ! $role->isSuperAdmin();
    }
}
